package com.rulecraft.decisionops.expressions.api;
import com.rulecraft.decisionops.expressions.DecisionExpressionService;import com.rulecraft.decisionops.expressions.DecisionExpressionService.*;import com.rulecraft.decisionops.identity.security.CurrentUser;import java.util.*;import org.springframework.http.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/projects/{projectId}/decision-services/{serviceId}/graph")
public class DecisionExpressionController {private final DecisionExpressionService service;public DecisionExpressionController(DecisionExpressionService service){this.service=service;}@GetMapping("/decision-expressions")List<ExpressionSummary> summaries(@PathVariable UUID projectId,@PathVariable UUID serviceId,Authentication authentication){return service.summaries(CurrentUser.require(authentication),projectId,serviceId);}@GetMapping("/nodes/{nodeId}/decision-expression")ResponseEntity<ExpressionView> get(@PathVariable UUID projectId,@PathVariable UUID serviceId,@PathVariable UUID nodeId,Authentication authentication){return service.find(CurrentUser.require(authentication),projectId,serviceId,nodeId).map(ResponseEntity::ok).orElseGet(()->ResponseEntity.noContent().build());}@PostMapping("/nodes/{nodeId}/decision-expression")@ResponseStatus(HttpStatus.CREATED)ExpressionView initialize(@PathVariable UUID projectId,@PathVariable UUID serviceId,@PathVariable UUID nodeId,Authentication authentication){return service.initialize(CurrentUser.require(authentication),projectId,serviceId,nodeId);}@PutMapping("/nodes/{nodeId}/decision-expression")ExpressionView update(@PathVariable UUID projectId,@PathVariable UUID serviceId,@PathVariable UUID nodeId,@RequestBody ExpressionCommand body,Authentication authentication){return service.update(CurrentUser.require(authentication),projectId,serviceId,nodeId,body);}@DeleteMapping("/nodes/{nodeId}/decision-expression")@ResponseStatus(HttpStatus.NO_CONTENT)void remove(@PathVariable UUID projectId,@PathVariable UUID serviceId,@PathVariable UUID nodeId,@RequestParam long version,Authentication authentication){service.remove(CurrentUser.require(authentication),projectId,serviceId,nodeId,version);}}
